{"content": "<!DOCTYPE html>
<html lang="ar" dir="rtl">
<head>
<meta charset="UTF-8">
<meta name="viewport" content="width=device-width, initial-scale=1.0">
<title>الطبقات الجيولوجية للأرض — Earth's Geological Layers</title>
<style>
  :root {
    --bg: #faf7f2;
    --surface: #ffffff;
    --text: #2b2118;
    --muted: #7a6a5b;
    --border: #e8e0d4;
    --accent: #b4551f;
    --shadow: 0 6px 24px rgba(43, 33, 24, 0.12);
    --crust: #8a6d4f;
    --mantle: #d97b3f;
    --outer: #e9a13b;
    --inner: #c0392b;
  }
  * { box-sizing: border-box; margin: 0; padding: 0; }
  body {
    font-family: "Segoe UI", Tahoma, "Noto Kufi Arabic", "Noto Naskh Arabic", "Amiri", Arial, sans-serif;
    background: var(--bg);
    color: var(--text);
    line-height: 1.8;
  }
  header {
    text-align: center;
    padding: 2.5rem 1.25rem 1.5rem;
    background: linear-gradient(160deg, #fdf3e7 0%, #f7e7d4 60%, #f3dcc4 100%);
    border-bottom: 1px solid var(--border);
  }
  header .eyebrow {
    font-size: 0.78rem; letter-spacing: 0.25em; text-transform: uppercase;
    color: var(--accent); font-weight: 700; margin-bottom: 0.5rem;
  }
  header h1 { font-size: clamp(1.7rem, 4.5vw, 2.6rem); font-weight: 800; color: #4a2c14; }
  header p { color: var(--muted); margin-top: 0.5rem; font-size: 1.05rem; }
  main {
    max-width: 1150px; margin: 0 auto; padding: 2rem 1.25rem 3rem;
    display: grid; grid-template-columns: 1.05fr 1fr; gap: 1.5rem; align-items: start;
  }
  @media (max-width: 900px) { main { grid-template-columns: 1fr; } }
  .diagram-card, .detail-card {
    background: var(--surface);
    border: 1px solid var(--border);
    border-radius: 16px;
    box-shadow: var(--shadow);
    padding: 1.5rem;
  }
  .diagram-card h2, .detail-card h2 {
    font-size: 1.15rem; color: #4a2c14; margin-bottom: 1rem;
    display: flex; align-items: center; gap: 0.5rem;
  }
  .diagram { width: 100%; height: auto; display: block; }
  .layer { cursor: pointer; transition: opacity 0.25s ease, filter 0.25s ease; }
  .layer:hover { filter: brightness(1.08); }
  .layer.dim { opacity: 0.35; }
  .layer.active { stroke: #2b2118; stroke-width: 3; }
  .detail-card .layer-name { font-size: 1.6rem; font-weight: 800; color: #4a2c14; }
  .detail-card .layer-en { color: var(--accent); font-size: 0.85rem; font-weight: 700; letter-spacing: 0.08em; text-transform: uppercase; margin-bottom: 0.75rem; }
  .badge-row { display: flex; flex-wrap: wrap; gap: 0.5rem; margin: 0.8rem 0; }
  .badge {
    background: #fdf1e3; border: 1px solid #ecc9a3; color: #6d3a12;
    border-radius: 999px; padding: 0.25rem 0.8rem; font-size: 0.85rem; font-weight: 700;
  }
  .detail-card ul { list-style: none; margin-top: 0.6rem; }
  .detail-card li {
    padding: 0.5rem 0 0.5rem 0.9rem; border-bottom: 1px dashed var(--border);
    border-inline-start: 3px solid #ecd4b8;
    margin-bottom: 0.4rem; font-size: 0.95rem;
  }
  .detail-card li:last-child { border-bottom: none; }
  .legend { display: flex; flex-wrap: wrap; gap: 0.6rem; margin-top: 1rem; }
  .legend button {
    font: inherit; cursor: pointer; border: 1px solid var(--border);
    background: #fff; border-radius: 10px; padding: 0.45rem 0.9rem;
    display: flex; align-items: center; gap: 0.5rem; font-size: 0.9rem;
    transition: transform 0.15s ease, box-shadow 0.15s ease;
  }
  .legend button:hover { transform: translateY(-2px); box-shadow: var(--shadow); }
  .dot { width: 14px; height: 14px; border-radius: 50%; flex-shrink: 0; }
  .legend button.active { border-color: var(--accent); background: #fdf1e3; }
  .hint { text-align: center; color: var(--muted); font-size: 0.85rem; margin-top: 0.75rem; }
  footer {
    text-align: center; color: var(--muted); font-size: 0.85rem;
    padding: 1.5rem 1rem; border-top: 1px solid var(--border);
  }
</style>
</head>
<body>

<header>
  <div class="eyebrow">Earth · الأرض</div>
  <h1>الطبقات الجيولوجية للأرض</h1>
  <p>قشرة الأرض، الوشاح، واللب — ثلاثة أقسام تبني كوكبنا</p>
</header>

<main>
  <!-- Diagram -->
  <div class="diagram-card">
    <h2>🌍 مقطع عرضي في كوكب الأرض</h2>
    <svg class="diagram" viewBox="0 0 440 440" role="img" aria-label="مقطع عرضي لطبقات كوكب الأرض">
      <!-- Crust -->
      <g id="g-crust">
        <circle class="layer" data-layer="crust" cx="220" cy="220" r="200" fill="#8a6d4f"/>
        <circle class="layer" data-layer="crust" cx="220" cy="220" r="182" fill="#d97b3f"/>
      </g>
      <!-- Mantle -->
      <g id="g-mantle">
        <circle class="layer" data-layer="mantle" cx="220" cy="220" r="182" fill="#d97b3f"/>
        <circle class="layer" data-layer="mantle" cx="220" cy="220" r="92" fill="#e9a13b"/>
      </g>
      <!-- Outer core -->
      <g id="g-outer">
        <circle class="layer" data-layer="outer" cx="220" cy="220" r="92" fill="#e9a13b"/>
        <circle class="layer" data-layer="outer" cx="220" cy="220" r="52" fill="#c0392b"/>
      </g>
      <!-- Inner core -->
      <g id="g-inner">
        <circle class="layer" data-layer="inner" cx="220" cy="220" r="52" fill="#c0392b"/>
        <circle cx="220" cy="220" r="22" fill="#e8c15a"/>
      </g>
      <!-- labels -->
      <text x="220" y="60" text-anchor="middle" font-size="14" font-weight="700" fill="#ffffff">قشرة الأرض</text>
      <text x="220" y="150" text-anchor="middle" font-size="15" font-weight="700" fill="#ffffff">الوشاح</text>
      <text x="220" y="230" text-anchor="middle" font-size="13" font-weight="700" fill="#4a2c14">اللب الخارجي</text>
      <text x="220" y="222" text-anchor="middle" font-size="11" font-weight="700" fill="#ffffff">اللب الداخلي</text>
    </svg>
    <div class="legend" id="legend">
      <button type="button" data-layer="crust" class="active"><span class="dot" style="background:#8a6d4f"></span>قشرة الأرض</button>
      <button type="button" data-layer="mantle"><span class="dot" style="background:#d97b3f"></span>الوشاح</button>
      <button type="button" data-layer="outer"><span class="dot" style="background:#e9a13b"></span>اللب الخارجي</button>
      <button type="button" data-layer="inner"><span class="dot" style="background:#c0392b"></span>اللب الداخلي</button>
    </div>
    <p class="hint">◀ انقر على طبقة في الرسم أو قائمة الأزرار لعرض تفاصيلها</p>
  </div>

