_FILES = 'abcdefgh'


def _parse_fen(fen):
    parts = fen.split()
    placement, active = parts[0], parts[1]
    board = [[None] * 8 for _ in range(8)]  # board[rank][file]; rank 0 = rank 1
    rank = 7
    for row in placement.split('/'):
        file = 0
        for ch in row:
            if ch.isdigit():
                file += int(ch)
            else:
                board[rank][file] = ch
                file += 1
        rank -= 1
    return board, active


def _to_fen(board, active):
    rows = []
    for rank in range(7, -1, -1):
        s, empty = '', 0
        for file in range(8):
            p = board[rank][file]
            if p is None:
                empty += 1
            else:
                if empty:
                    s += str(empty)
                    empty = 0
                s += p
        if empty:
            s += str(empty)
        rows.append(s)
    return '/'.join(rows) + ' ' + active + ' - - 0 1'


def _uci(move):
    r, f, tr, tf = move
    return _FILES[f] + str(r + 1) + _FILES[tf] + str(tr + 1)


def _generate_moves(board, active):
    white = active == 'w'
    moves = []
    for r in range(8):
        for f in range(8):
            p = board[r][f]
            if p is None:
                continue
            if p.isupper() != white:
                continue
            letter = p.upper()
            if letter == 'P':
                direction = 1 if white else -1
                start_rank = 1 if white else 6
                last_rank = 7 if white else 0
                nr = r + direction
                if 0 <= nr <= 7:
                    # single push (no promotion: pawns may not reach last rank)
                    if board[nr][f] is None and nr != last_rank:
                        moves.append((r, f, nr, f))
                        # double push from starting rank
                        r2 = r + 2 * direction
                        if (r == start_rank and board[r2][f] is None):
                            moves.append((r, f, r2, f))
                    # captures
                    for df in (-1, 1):
                        nf = f + df
                        if 0 <= nf < 8 and nr != last_rank:
                            dest = board[nr][nf]
                            if dest is not None and (dest.isupper() != white):
                                moves.append((r, f, nr, nf))
            elif letter == 'N':
                for dr, df in ((2, 1), (2, -1), (-2, 1), (-2, -1),
                               (1, 2), (1, -2), (-1, 2), (-1, -2)):
                    nr, nf = r + dr, f + df
                    if 0 <= nr < 8 and 0 <= nf < 8:
                        dest = board[nr][nf]
                        if dest is None or (dest.isupper() != white):
                            moves.append((r, f, nr, nf))
            elif letter == 'K':
                for dr in (-1, 0, 1):
                    for df in (-1, 0, 1):
                        if dr == 0 and df == 0:
                            continue
                        nr, nf = r + dr, f + df
                        if 0 <= nr < 8 and 0 <= nf < 8:
                            dest = board[nr][nf]
                            if dest is None or (dest.isupper() != white):
                                moves.append((r, f, nr, nf))
            elif letter in ('B', 'R', 'Q'):
                dirs = []
                if letter in ('B', 'Q'):
                    dirs += [(1, 1), (1, -1), (-1, 1), (-1, -1)]
                if letter in ('R', 'Q'):
                    dirs += [(1, 0), (-1, 0), (0, 1), (0, -1)]
                for dr, df in dirs:
                    nr, nf = r + dr, f + df
                    while 0 <= nr < 8 and 0 <= nf < 8:
                        dest = board[nr][nf]
                        if dest is None:
                            moves.append((r, f, nr, nf))
                        else:
                            if dest.isupper() != white:
                                moves.append((r, f, nr, nf))
                            break
                        nr += dr
                        nf += df
    return moves


def _apply(board, move):
    r, f, tr, tf = move
    nb = [row[:] for row in board]
    nb[tr][tf] = nb[r][f]
    nb[r][f] = None
    return nb


def _perft(board, active, depth):
    if depth == 0:
        return 1
    total = 0
    for move in _generate_moves(board, active):
        nb = _apply(board, move)
        total += _perft(nb, 'b' if active == 'w' else 'w', depth - 1)
    return total


def legal_moves(fen):
    board, active = _parse_fen(fen)
    return [_uci(m) for m in _generate_moves(board, active)]


def perft(fen, depth):
    board, active = _parse_fen(fen)
    return _perft(board, active, depth)
