_KING_DELTAS = ((dr, df) for dr in (-1, 0, 1) for df in (-1, 0, 1) if not (dr == 0 and df == 0))
_CARDINAL_DIRS = ((1, 0), (-1, 0), (0, 1), (0, -1))
_DIAG_DIRS = ((1, 1), (1, -1), (-1, 1), (-1, -1))


def _parse_fen(fen):
    parts = fen.split()
    placement, active = parts[0], parts[1]
    castling = parts[2] if len(parts) > 2 else '-'
    if castling == '-':
